use vstd::prelude::*;

verus! {

pub enum ExpandedVector<T> {
    RowVector(Vec<T>),
    ColumnVector(Vec<T>),
}

/// Expand a 1-D vector into a tagged "row" or "column" wrapper depending on `axis`.
///
/// Semantics:
/// - axis == 0  ==> RowVector(a)   (same elements, same order)
/// - axis == 1  ==> ColumnVector(a) (same elements, same order)
pub fn expand_dims<T>(a: Vec<T>, axis: usize) -> (out: ExpandedVector<T>)
    requires
        axis <= 1,
    ensures
        axis == 0 ==> match out {
            ExpandedVector::RowVector(v) => v@ == a@,
            _ => false,
        },
        axis == 1 ==> match out {
            ExpandedVector::ColumnVector(v) => v@ == a@,
            _ => false,
        },
{
    if axis == 0 {
        ExpandedVector::RowVector(a)
    } else {
        // Under the precondition axis <= 1, any nonzero axis must be 1.
        assert(axis == 1);
        ExpandedVector::ColumnVector(a)
    }
}

} // verus!

